import 'package:flutter/material.dart'; import '../models/course_model.dart'; class CourseCard extends StatelessWidget { final CourseModel course; final VoidCallback? onTap; const CourseCard({super.key,required this.course,this.onTap}); @override Widget build(BuildContext c)=>Card(child:ListTile(onTap:onTap,title:Text(course.name),subtitle:Text(course.description),trailing:Text('${course.passingScore.toStringAsFixed(0)}%'))); }